  </Box>
</Box>

  

  {/* Navigation Buttons */}
  <Box sx={{ mt: 3, display: 'flex', justifyContent: 'space-between' }}>
    <Button variant="outlined" disabled>
      Back
    </Button>
    <Button variant="contained" color="primary">
      Next
    </Button>
  </Box>
</Box>
</Box>
</Box>
</Box>
</Box>
</Box>
  );
};

export default TrailerSpecification;
